  function comparable(value){var copy=JSON.parse(JSON.stringify(value||{}));delete copy.createdAt;delete copy.updatedAt;delete copy.review;return copy;}
  function snapshotChanges(a,b){var result=[];['items','relations','conflicts'].forEach(function(kind){var x=kind==='items'?a.items:Object.fromEntries((a[kind]||[]).map(function(r){return[r.id,r];})),y=kind==='items'?b.items:Object.fromEntries((b[kind]||[]).map(function(r){return[r.id,r];}));new Set(Object.keys(x||{}).concat(Object.keys(y||{}))).forEach(function(id){if(JSON.stringify(comparable(x[id]))!==JSON.stringify(comparable(y[id])))result.push({id:id,before:x[id],after:y[id],kind:!x[id]?'added':!y[id]?'deleted':'modified'});});});return result;}
  function snapshotText(x){
    if(!x)return '—';
    var aliases={word:'word',others:'others',othersView:'others',mine:'mine',myUsage:'mine',focusReason:'focusWhy',why:'whyRelated',reason:'reason',supportsA:'supportsA',supportsB:'supportsB',priority:'coordinate',mitigationJudgment:'mitigation',alternatives:'alternatives',order:'priority',from:'from',to:'to',kind:'associationKind',scope:'scope'};
    var values=[];
    if(x.principleId)values.push(principleName(x.principleId));
    if(x.text)values.push(x.text);
    Object.keys(aliases).forEach(function(k){if(x[k]&&!((k==='othersView'&&x.others!==undefined)||(k==='myUsage'&&x.mine!==undefined)))values.push(t(aliases[k])+': '+(k==='scope'?t(x[k]==='case'?'caseScope':'generalScope'):x[k]));});
    ['actors','basisRefs','appliesTo'].forEach(function(k){if(x[k]&&x[k].length)values.push(t(k==='actors'?'actor':k==='basisRefs'?'basis':'questionTarget')+': '+x[k].join(' · '));});
    if(x.isCore!==undefined)values.push(t('core')+': '+bi(x.isCore?'是':'否',x.isCore?'Yes':'No'));
    return values.join('\n\n')||x.id||'—';
  }
