  document.addEventListener('change',function(e){if(e.target.matches('#basis-form [name="basis"]'))document.getElementById('basis-count').textContent=modal.querySelectorAll('[name="basis"]:checked').length+' '+bi('项依据已选','references selected');});
  document.addEventListener('click',function(e){if(archiveMenuOpen&&!e.target.closest('[data-testid="archive-menu"]')&&!e.target.closest('#archive-menu-panel'))closeArchiveMenu();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&archiveMenuOpen)closeArchiveMenu();});
  document.addEventListener('click',onClick);document.addEventListener('input',function(e){if(e.target.matches('textarea[data-item],input[data-item]:not([type="checkbox"]),textarea[data-conflict],input[data-conflict]'))updateInput(e);});document.addEventListener('change',function(e){if(e.target.matches('select[data-item],select[data-conflict],input[type="checkbox"][data-item],[data-status],[data-review],[data-checklist],[data-applies]'))updateInput(e);});document.addEventListener('submit',submit);
  document.addEventListener('dragstart',function(e){var el=e.target.closest('[data-drag]');if(el&&!presentation){dragId=el.dataset.drag;e.dataTransfer.setData('text/plain',dragId);}});
  document.addEventListener('dragover',function(e){if(e.target.closest('[data-drag]'))e.preventDefault();});
  document.addEventListener('drop',function(e){var el=e.target.closest('[data-drag]');if(!el||!dragId||presentation)return;e.preventDefault();var list=rows('PA').sort(function(a,b){return(a.order||0)-(b.order||0);}),from=list.findIndex(function(x){return x.id===dragId;}),to=list.findIndex(function(x){return x.id===el.dataset.drag;});if(from>=0&&to>=0){var row=list.splice(from,1)[0];list.splice(to,0,row);list.forEach(function(x,i){dispatch('UPDATE_ITEM',{id:x.id,fields:{order:i+1}});});}dragId=null;});
  document.getElementById('project-file').addEventListener('change',function(e){var file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){toast(t('fileLarge'));return;}var reader=new FileReader();reader.onload=function(){var before=JSON.stringify(engine.getState()),text=reader.result,parsed;try{parsed=JSON.parse(text);}catch(err){importFailDialog(bi('无法解析 JSON。','Invalid JSON.'));return;}var bundled=parsed&&parsed.format==='fieldnotes-project-v1',payload=bundled?parsed.state:parsed,pack=bundled?parsed.caseData:data,checked=pack&&cases.validateAnalysisPayload?cases.validateAnalysisPayload(payload,pack):{ok:false,message:t('invalidImport')};if(!checked.ok){if(JSON.stringify(engine.getState())!==before)toast(bi('状态异常：请刷新页面。','State mismatch; refresh the page.'));importFailDialog(checked.message||t('invalidImport'));return;}confirmAction(t('importConfirm'),function(){var result=cases.importProject(text);if(result.ok){if(result.compatMode)toast(bi('当前使用兼容模式，部分保护能力不可用。','Compatibility mode: some protections are unavailable.'));attachCase();toast(t('imported'));view='workbook';render();}else importFailDialog(result.message||t('invalidImport'));});};reader.onerror=function(){toast(t('invalidImport'));};reader.readAsText(file);});
